import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const SAFE_KEY = /^[a-zA-Z0-9_-]+\.[a-z0-9]+$/;

/** Flat file storage for processed images. Keys are generated by us, never by users. */
export class ImageStore {
	readonly #root: string;

	constructor(rootDir: string) {
		this.#root = resolve(rootDir);
	}

	async save(key: string, data: Buffer): Promise<void> {
		await mkdir(this.#root, { recursive: true });
		await writeFile(this.#path(key), data);
	}

	/** Returns `null` when the file does not exist. */
	async read(key: string): Promise<Buffer | null> {
		try {
			return await readFile(this.#path(key));
		} catch (err) {
			if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
			throw err;
		}
	}

	async remove(key: string): Promise<void> {
		await rm(this.#path(key), { force: true });
	}

	#path(key: string): string {
		if (!SAFE_KEY.test(key)) throw new Error(`Invalid storage key: ${key}`);
		return join(this.#root, key);
	}
}
